  j constant jsonb := $j$[
{"id":"c35c3a59-08d3-414a-8092-2f9036651e0c","recipe_group_id":"5db2c8e6-a3f2-4be8-84b8-620b6ade903c","language":"es","slug":"ensalada-de-pollo-y-aguacate","public_path":"/ensalada-de-pollo-y-aguacate","source_url":null,"title":"Ensalada de pollo y aguacate","excerpt":"Ensalada de pollo y aguacate con tomates cherry, cebolla morada y cilantro, aliñada con limón y aceite de oliva. Para 4 personas, lista en 30 minutos.","summary":"La ensalada de pollo y aguacate se prepara cociendo la pechuga en agua con sal, deshebrándola y mezclándola con tomates cherry, cebolla morada y cilantro, con un aliño de aceite de oliva y limón. El aguacate se incorpora al final para que no se deshaga, y se sirve sobre una cama de lechuga.\n\nLa ensalada tarda 30 minutos entre preparación y cocción. Rinde 4 porciones.","category":"Ensaladas","difficulty":"Fácil","course":"Plato principal","cuisine":"Latinoamericana","prep_time_minutes":15,"cook_time_minutes":15,"total_time_minutes":30,"servings":4,"keywords":["ensalada de pollo y aguacate","receta de ensalada de pollo y aguacate","cómo hacer ensalada de pollo y aguacate","ensalada de pollo desmenuzado","ensalada de pollo con aguacate y tomate","ensalada de pollo fácil","ensalada de pollo saludable"],"ingredients":[{"name":"pechuga de pollo","amount":"500","unit":"g","group":"Para la ensalada"},{"name":"aguacates maduros","amount":"2","unit":"","group":"Para la ensalada"},{"name":"tomates cherry","amount":"200","unit":"g","group":"Para la ensalada"},{"name":"cebolla morada","amount":"1/2","unit":"","group":"Para la ensalada"},{"name":"cilantro fresco","amount":"15","unit":"g","group":"Para la ensalada"},{"name":"lechuga","amount":"200","unit":"g","group":"Para la ensalada"},{"name":"sal","amount":"1","unit":"cucharadita","group":"Para la ensalada"},{"name":"aceite de oliva","amount":"3","unit":"cucharada","group":"Para el aliño"},{"name":"limones","amount":"2","unit":"","group":"Para el aliño"},{"name":"pimienta negra molida","amount":"1","unit":"pizca","group":"Para el aliño"}],"steps":[{"title":"Prepara los ingredientes","content":"Reúne 500 g de pechuga de pollo, 2 aguacates maduros, 200 g de tomates cherry, 1/2 cebolla morada, 15 g de cilantro, 200 g de lechuga y 2 limones. Lava las verduras y el cilantro.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-01.webp","image_alt":"Ensalada de pollo y aguacate: Prepara los ingredientes"},{"title":"Cuece la pechuga","content":"Pon la pechuga en una olla, cúbrela con agua, añade 1 cucharadita de sal y cuece 15 minutos a fuego medio, hasta que esté hecha por dentro.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-02.webp","image_alt":"Ensalada de pollo y aguacate: Cuece la pechuga"},{"title":"Deshebra el pollo","content":"Saca la pechuga, déjala templar unos minutos y deshébrala con dos tenedores.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-03.webp","image_alt":"Ensalada de pollo y aguacate: Deshebra el pollo"},{"title":"Corta las verduras","content":"Corta los aguacates en cubos, los tomates cherry por la mitad y la cebolla morada en tiras finas. Pica el cilantro.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-04.webp","image_alt":"Ensalada de pollo y aguacate: Corta las verduras"},{"title":"Prepara el aliño","content":"Bate en un bol 3 cucharadas de aceite de oliva con el jugo de 1 limón y medio (unos 45 ml), 1 pizca de sal y 1 pizca de pimienta.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-05.webp","image_alt":"Ensalada de pollo y aguacate: Prepara el aliño"},{"title":"Mezcla la ensalada","content":"En un bol grande, mezcla el pollo deshebrado, los tomates, la cebolla y el cilantro con el aliño.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-06.webp","image_alt":"Ensalada de pollo y aguacate: Mezcla la ensalada"},{"title":"Añade el aguacate","content":"Incorpora el aguacate al final, con movimientos suaves para que no se deshaga.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-07.webp","image_alt":"Ensalada de pollo y aguacate: Añade el aguacate"},{"title":"Sirve","content":"Sirve sobre una cama de lechuga, con cilantro por encima y el medio limón restante cortado en gajos.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-08.webp","image_alt":"Ensalada de pollo y aguacate: Sirve"}],"image_url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","gallery":[{"url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","alt":"Ensalada de pollo y aguacate"}],"notes":"Para que el pollo quede jugoso, no lo cuezas más de lo necesario y déjalo templar antes de deshebrarlo. Elige aguacates maduros pero firmes, que se corten en cubos sin deshacerse. Añade el aguacate justo antes de servir, porque se oscurece con el aire; el limón ayuda a retrasarlo. Si preparas la ensalada con antelación, guarda aparte el aguacate y el aliño. Se conserva hasta 2 días en la nevera, con el aguacate fresco añadido al momento.","nutrition":{"calories":373,"protein_g":30.9,"carbs_g":11,"fat_g":23.5,"sodium_mg":80,"serving_size":"1 porción (1/4 de la receta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 4 porciones. Se usan 500 g de pechuga de pollo cruda, 270 g de pulpa de aguacate, 200 g de tomates cherry, 60 g de cebolla morada, 15 g de cilantro, 200 g de lechuga, 40,5 g de aceite de oliva y 46 g de jugo de limón. La sal, la pimienta y el limón en gajos para servir no se cuentan.","note":"Estimación por porción. La pechuga se calcula cruda y sin piel; el peso de la pulpa del aguacate varía con su tamaño. No se descuenta lo que el pollo pierde al cocerse.","inputs":[{"fdc_id":"171077","description":"Chicken, broilers or fryers, breast, meat only, raw (500 g de pechuga)","grams":500,"per100":{"calories":120,"protein_g":22.5,"carbs_g":0,"fat_g":2.62,"saturated_fat_g":0.563,"fiber_g":0,"sodium_mg":45}},{"fdc_id":"171705","description":"Avocados, raw, all commercial varieties (2 aguacates, pulpa ≈ 270 g)","grams":270,"per100":{"calories":160,"protein_g":2.0,"carbs_g":8.53,"fat_g":14.66,"saturated_fat_g":2.126,"fiber_g":6.7,"sodium_mg":7}},{"fdc_id":"170457","description":"Tomatoes, red, ripe, raw (200 g de tomates cherry)","grams":200,"per100":{"calories":18,"protein_g":0.88,"carbs_g":3.89,"fat_g":0.2,"saturated_fat_g":0.028,"fiber_g":1.2,"sodium_mg":5}},{"fdc_id":"170000","description":"Onions, raw (1/2 cebolla morada ≈ 60 g)","grams":60,"per100":{"calories":40,"protein_g":1.1,"carbs_g":9.34,"fat_g":0.1,"saturated_fat_g":0.042,"fiber_g":1.7,"sodium_mg":4}},{"fdc_id":"169997","description":"Coriander (cilantro) leaves, raw (15 g)","grams":15,"per100":{"calories":23,"protein_g":2.13,"carbs_g":3.67,"fat_g":0.52,"saturated_fat_g":0.014,"fiber_g":2.8,"sodium_mg":46}},{"fdc_id":"169247","description":"Lettuce, green leaf, raw (200 g)","grams":200,"per100":{"calories":15,"protein_g":1.36,"carbs_g":2.26,"fat_g":0.15,"saturated_fat_g":0.02,"fiber_g":1.3,"sodium_mg":28}},{"fdc_id":"171413","description":"Oil, olive, salad or cooking (3 cucharadas ≈ 40,5 g)","grams":40.5,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.81,"fiber_g":0,"sodium_mg":2}},{"fdc_id":"167746","description":"Lemon juice, raw (jugo de 1 limón y medio ≈ 46 g)","grams":46,"per100":{"calories":22,"protein_g":0.35,"carbs_g":6.9,"fat_g":0.24,"saturated_fat_g":0.04,"fiber_g":0.3,"sodium_mg":1}}]},"seo":{"title":"Ensalada de pollo y aguacate fácil y fresca | Manual de Cocina","description":"Ensalada de pollo y aguacate con tomates cherry, cebolla morada y cilantro, aliñada con limón y aceite de oliva. Para 4 personas, lista en 30 minutos.","image_variants":["/recetas/ensalada-de-pollo-y-aguacate/portada-1x1.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-4x3.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-16x9.webp"],"faq":[{"q":"¿Cómo evito que el aguacate se oscurezca en la ensalada?","a":"Añádelo justo antes de servir y mézclalo con cuidado. El jugo de limón del aliño ayuda a retrasar que se oscurezca."},{"q":"¿Puedo usar pollo ya cocido?","a":"Sí. Si tienes pollo cocido o asado, deshébralo y sáltate los pasos de cocción; los 15 minutos de cocción de la pechuga son lo único que cambia."},{"q":"¿Se puede preparar con antelación?","a":"Sí, hasta 2 días antes en la nevera. Guarda aparte el aguacate y el aliño, y mézclalos justo antes de servir."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"2f97c436-ee76-53d4-beae-a1315afb0198","recipe_group_id":"5db2c8e6-a3f2-4be8-84b8-620b6ade903c","language":"de","slug":"haehnchen-avocado-salat","public_path":"/de/haehnchen-avocado-salat","source_url":null,"title":"Hähnchen-Avocado-Salat","excerpt":"Hähnchen-Avocado-Salat mit Kirschtomaten, roter Zwiebel und Koriander, mit Zitrone und Olivenöl angemacht. Für 4 Personen, fertig in 30 Minuten.","summary":"Für den Hähnchen-Avocado-Salat wird die Hähnchenbrust in Salzwasser gegart, zerzupft und mit Kirschtomaten, roter Zwiebel und Koriander in einem Dressing aus Olivenöl und Zitrone vermengt. Die Avocado kommt zuletzt dazu, damit sie nicht zerfällt, und serviert wird auf einem Bett aus Salat.\n\nDer Salat braucht 30 Minuten für Vorbereitung und Garen. Ergibt 4 Portionen.","category":"Salate","difficulty":"Einfach","course":"Hauptgericht","cuisine":"Lateinamerikanisch","prep_time_minutes":15,"cook_time_minutes":15,"total_time_minutes":30,"servings":4,"keywords":["Hähnchen-Avocado-Salat","Hähnchen-Avocado-Salat Rezept","Hähnchensalat mit Avocado","Hähnchensalat mit Avocado und Tomaten","zerzupfter Hähnchensalat","Hähnchensalat einfach","ensalada de pollo y aguacate"],"ingredients":[{"name":"Hähnchenbrust","amount":"500","unit":"g","group":"Für den Salat"},{"name":"reife Avocados","amount":"2","unit":"","group":"Für den Salat"},{"name":"Kirschtomaten","amount":"200","unit":"g","group":"Für den Salat"},{"name":"rote Zwiebel","amount":"1/2","unit":"","group":"Für den Salat"},{"name":"frischer Koriander","amount":"15","unit":"g","group":"Für den Salat"},{"name":"Blattsalat","amount":"200","unit":"g","group":"Für den Salat"},{"name":"Salz","amount":"1","unit":"Teelöffel","group":"Für den Salat"},{"name":"Olivenöl","amount":"3","unit":"Esslöffel","group":"Für das Dressing"},{"name":"Zitronen","amount":"2","unit":"","group":"Für das Dressing"},{"name":"schwarzer Pfeffer, gemahlen","amount":"1","unit":"Prise","group":"Für das Dressing"}],"steps":[{"title":"Zutaten vorbereiten","content":"500 g Hähnchenbrust, 2 reife Avocados, 200 g Kirschtomaten, 1/2 rote Zwiebel, 15 g Koriander, 200 g Blattsalat und 2 Zitronen bereitlegen. Gemüse und Koriander waschen.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-01.webp","image_alt":"Hähnchen-Avocado-Salat: Zutaten vorbereiten"},{"title":"Hähnchenbrust garen","content":"Die Hähnchenbrust in einen Topf legen, mit Wasser bedecken, 1 Teelöffel Salz zugeben und 15 Minuten bei mittlerer Hitze garen, bis sie durchgegart ist.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-02.webp","image_alt":"Hähnchen-Avocado-Salat: Hähnchenbrust garen"},{"title":"Hähnchen zerzupfen","content":"Die Hähnchenbrust herausnehmen, einige Minuten abkühlen lassen und mit zwei Gabeln zerzupfen.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-03.webp","image_alt":"Hähnchen-Avocado-Salat: Hähnchen zerzupfen"},{"title":"Gemüse schneiden","content":"Die Avocados würfeln, die Kirschtomaten halbieren und die rote Zwiebel in feine Streifen schneiden. Den Koriander hacken.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-04.webp","image_alt":"Hähnchen-Avocado-Salat: Gemüse schneiden"},{"title":"Dressing zubereiten","content":"In einer Schüssel 3 Esslöffel Olivenöl mit dem Saft von 1 1/2 Zitronen (etwa 45 ml), 1 Prise Salz und 1 Prise Pfeffer verrühren.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-05.webp","image_alt":"Hähnchen-Avocado-Salat: Dressing zubereiten"},{"title":"Salat vermengen","content":"In einer großen Schüssel das zerzupfte Hähnchen, die Tomaten, die Zwiebel und den Koriander mit dem Dressing vermengen.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-06.webp","image_alt":"Hähnchen-Avocado-Salat: Salat vermengen"},{"title":"Avocado zugeben","content":"Die Avocado zuletzt mit sanften Bewegungen unterheben, damit sie nicht zerfällt.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-07.webp","image_alt":"Hähnchen-Avocado-Salat: Avocado zugeben"},{"title":"Servieren","content":"Auf einem Bett aus Blattsalat anrichten, mit Koriander bestreuen und mit der restlichen halben Zitrone in Spalten servieren.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-08.webp","image_alt":"Hähnchen-Avocado-Salat: Servieren"}],"image_url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","gallery":[{"url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","alt":"Hähnchen-Avocado-Salat"}],"notes":"Damit das Hähnchen saftig bleibt, nicht länger als nötig garen und vor dem Zerzupfen abkühlen lassen. Reife, aber noch feste Avocados wählen, die sich würfeln lassen, ohne zu zerfallen. Die Avocado erst kurz vor dem Servieren zugeben, da sie an der Luft dunkel wird; der Zitronensaft verzögert das. Wird der Salat vorbereitet, Avocado und Dressing getrennt aufbewahren. Hält sich bis zu 2 Tage im Kühlschrank, die frische Avocado wird erst zum Servieren zugegeben.","nutrition":{"calories":373,"protein_g":30.9,"carbs_g":11,"fat_g":23.5,"sodium_mg":80,"serving_size":"1 Portion (1/4 des Rezepts)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 4 Portionen geteilt. Verwendet werden 500 g rohe Hähnchenbrust, 270 g Avocadofruchtfleisch, 200 g Kirschtomaten, 60 g rote Zwiebel, 15 g Koriander, 200 g Blattsalat, 40,5 g Olivenöl und 46 g Zitronensaft. Salz, Pfeffer und die Zitronenspalten zum Servieren werden nicht gezählt.","note":"Schätzung pro Portion. Die Hähnchenbrust wird roh und ohne Haut berechnet; das Gewicht des Avocadofruchtfleischs hängt von der Größe ab. Was das Hähnchen beim Garen verliert, wird nicht abgezogen."},"seo":{"title":"Hähnchen-Avocado-Salat, einfach und frisch | Manual de Cocina","description":"Hähnchen-Avocado-Salat mit Kirschtomaten, roter Zwiebel und Koriander, mit Zitrone und Olivenöl angemacht. Für 4 Personen, fertig in 30 Minuten.","image_variants":["/recetas/ensalada-de-pollo-y-aguacate/portada-1x1.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-4x3.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-16x9.webp"],"faq":[{"q":"Wie verhindere ich, dass die Avocado im Salat dunkel wird?","a":"Die Avocado erst kurz vor dem Servieren zugeben und vorsichtig unterheben. Der Zitronensaft im Dressing verzögert das Dunkelwerden."},{"q":"Kann ich bereits gegartes Hähnchen verwenden?","a":"Ja. Gegartes oder gebratenes Hähnchen einfach zerzupfen und die Garschritte überspringen; nur die 15 Minuten Garzeit der Hähnchenbrust entfallen."},{"q":"Kann man den Salat vorbereiten?","a":"Ja, bis zu 2 Tage im Kühlschrank. Avocado und Dressing getrennt aufbewahren und erst kurz vor dem Servieren mischen."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"cc983d48-2a5d-5261-8418-2197dbc22ce6","recipe_group_id":"5db2c8e6-a3f2-4be8-84b8-620b6ade903c","language":"en","slug":"chicken-avocado-salad","public_path":"/en/chicken-avocado-salad","source_url":null,"title":"Chicken and Avocado Salad","excerpt":"Chicken and avocado salad with cherry tomatoes, red onion and cilantro, dressed with lemon and olive oil. Serves 4, ready in 30 minutes.","summary":"Chicken and avocado salad is made by poaching the chicken breast in salted water, shredding it and tossing it with cherry tomatoes, red onion and cilantro in an olive oil and lemon dressing. The avocado goes in last so it does not fall apart, and the salad is served on a bed of lettuce.\n\nThe salad takes 30 minutes from prep to table. It serves 4.","category":"Salads","difficulty":"Easy","course":"Main course","cuisine":"Latin American","prep_time_minutes":15,"cook_time_minutes":15,"total_time_minutes":30,"servings":4,"keywords":["chicken and avocado salad","chicken avocado salad recipe","how to make chicken avocado salad","shredded chicken salad","chicken salad with avocado and tomato","easy chicken salad","ensalada de pollo y aguacate"],"ingredients":[{"name":"chicken breast","amount":"500","unit":"g","group":"For the salad"},{"name":"ripe avocados","amount":"2","unit":"","group":"For the salad"},{"name":"cherry tomatoes","amount":"200","unit":"g","group":"For the salad"},{"name":"red onion","amount":"1/2","unit":"","group":"For the salad"},{"name":"fresh cilantro","amount":"15","unit":"g","group":"For the salad"},{"name":"lettuce","amount":"200","unit":"g","group":"For the salad"},{"name":"salt","amount":"1","unit":"teaspoon","group":"For the salad"},{"name":"olive oil","amount":"3","unit":"tablespoon","group":"For the dressing"},{"name":"lemons","amount":"2","unit":"","group":"For the dressing"},{"name":"ground black pepper","amount":"1","unit":"pinch","group":"For the dressing"}],"steps":[{"title":"Prepare the ingredients","content":"Gather 500 g chicken breast, 2 ripe avocados, 200 g cherry tomatoes, 1/2 red onion, 15 g cilantro, 200 g lettuce and 2 lemons. Wash the vegetables and the cilantro.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-01.webp","image_alt":"Chicken and Avocado Salad: Prepare the ingredients"},{"title":"Poach the chicken","content":"Put the chicken breast in a pot, cover it with water, add 1 teaspoon salt and simmer for 15 minutes over medium heat, until cooked through.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-02.webp","image_alt":"Chicken and Avocado Salad: Poach the chicken"},{"title":"Shred the chicken","content":"Remove the chicken, let it cool for a few minutes and shred it with two forks.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-03.webp","image_alt":"Chicken and Avocado Salad: Shred the chicken"},{"title":"Cut the vegetables","content":"Dice the avocados, halve the cherry tomatoes and slice the red onion into thin strips. Chop the cilantro.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-04.webp","image_alt":"Chicken and Avocado Salad: Cut the vegetables"},{"title":"Make the dressing","content":"Whisk 3 tablespoons olive oil in a bowl with the juice of 1 1/2 lemons (about 45 ml), 1 pinch salt and 1 pinch pepper.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-05.webp","image_alt":"Chicken and Avocado Salad: Make the dressing"},{"title":"Mix the salad","content":"In a large bowl, toss the shredded chicken, tomatoes, onion and cilantro with the dressing.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-06.webp","image_alt":"Chicken and Avocado Salad: Mix the salad"},{"title":"Add the avocado","content":"Fold in the avocado last, gently so it does not fall apart.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-07.webp","image_alt":"Chicken and Avocado Salad: Add the avocado"},{"title":"Serve","content":"Serve on a bed of lettuce, topped with cilantro and the remaining half lemon cut into wedges.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-08.webp","image_alt":"Chicken and Avocado Salad: Serve"}],"image_url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","gallery":[{"url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","alt":"Chicken and Avocado Salad"}],"notes":"To keep the chicken juicy, do not cook it longer than needed and let it cool before shredding. Choose ripe but firm avocados that can be diced without turning to mush. Add the avocado just before serving, since it darkens in the air; the lemon juice helps slow that. If you make the salad ahead, store the avocado and the dressing separately. It keeps up to 2 days in the fridge, with fresh avocado added at the last minute.","nutrition":{"calories":373,"protein_g":30.9,"carbs_g":11,"fat_g":23.5,"sodium_mg":80,"serving_size":"1 serving (1/4 of the recipe)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 4 servings. It uses 500 g raw chicken breast, 270 g avocado flesh, 200 g cherry tomatoes, 60 g red onion, 15 g cilantro, 200 g lettuce, 40.5 g olive oil and 46 g lemon juice. Salt, pepper and the lemon wedges for serving are not counted.","note":"Estimate per serving. The chicken breast is calculated raw and skinless; the weight of the avocado flesh varies with its size. No deduction is made for what the chicken loses when cooked."},"seo":{"title":"Chicken and Avocado Salad, Easy and Fresh | Manual de Cocina","description":"Chicken and avocado salad with cherry tomatoes, red onion and cilantro, dressed with lemon and olive oil. Serves 4, ready in 30 minutes.","image_variants":["/recetas/ensalada-de-pollo-y-aguacate/portada-1x1.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-4x3.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-16x9.webp"],"faq":[{"q":"How do I keep the avocado from browning in the salad?","a":"Add it just before serving and fold it in gently. The lemon juice in the dressing helps slow the browning."},{"q":"Can I use pre-cooked chicken?","a":"Yes. Shred cooked or roast chicken and skip the cooking step; only the 15 minutes of poaching the breast are saved."},{"q":"Can the salad be made ahead?","a":"Yes, up to 2 days ahead in the fridge. Store the avocado and the dressing separately and mix them in just before serving."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"af2bc92f-2458-5931-9531-cec429b9a6ba","recipe_group_id":"5db2c8e6-a3f2-4be8-84b8-620b6ade903c","language":"fr","slug":"salade-de-poulet-et-avocat","public_path":"/fr/salade-de-poulet-et-avocat","source_url":null,"title":"Salade de poulet et avocat","excerpt":"Salade de poulet et avocat aux tomates cerises, oignon rouge et coriandre, assaisonnée de citron et d'huile d'olive. Pour 4 personnes, prête en 30 minutes.","summary":"La salade de poulet et avocat se prépare en pochant le blanc de poulet dans de l'eau salée, en l'effilochant et en le mélangeant avec des tomates cerises, de l'oignon rouge et de la coriandre dans une vinaigrette à l'huile d'olive et au citron. L'avocat s'ajoute en dernier pour ne pas s'écraser, et la salade se sert sur un lit de laitue.\n\nLa salade demande 30 minutes entre préparation et cuisson. Pour 4 portions.","category":"Salades","difficulty":"Facile","course":"Plat principal","cuisine":"Latino-américaine","prep_time_minutes":15,"cook_time_minutes":15,"total_time_minutes":30,"servings":4,"keywords":["salade de poulet et avocat","recette salade de poulet et avocat","comment faire une salade de poulet et avocat","salade de poulet effiloché","salade de poulet avocat tomates","salade de poulet facile","ensalada de pollo y aguacate"],"ingredients":[{"name":"blanc de poulet","amount":"500","unit":"g","group":"Pour la salade"},{"name":"avocats mûrs","amount":"2","unit":"","group":"Pour la salade"},{"name":"tomates cerises","amount":"200","unit":"g","group":"Pour la salade"},{"name":"oignon rouge","amount":"1/2","unit":"","group":"Pour la salade"},{"name":"coriandre fraîche","amount":"15","unit":"g","group":"Pour la salade"},{"name":"laitue","amount":"200","unit":"g","group":"Pour la salade"},{"name":"sel","amount":"1","unit":"cuillère à café","group":"Pour la salade"},{"name":"huile d'olive","amount":"3","unit":"cuillère à soupe","group":"Pour la vinaigrette"},{"name":"citrons","amount":"2","unit":"","group":"Pour la vinaigrette"},{"name":"poivre noir moulu","amount":"1","unit":"pincée","group":"Pour la vinaigrette"}],"steps":[{"title":"Préparer les ingrédients","content":"Réunir 500 g de blanc de poulet, 2 avocats mûrs, 200 g de tomates cerises, 1/2 oignon rouge, 15 g de coriandre, 200 g de laitue et 2 citrons. Laver les légumes et la coriandre.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-01.webp","image_alt":"Salade de poulet et avocat: Préparer les ingrédients"},{"title":"Pocher le poulet","content":"Mettre le blanc de poulet dans une casserole, le couvrir d'eau, ajouter 1 cuillère à café de sel et cuire 15 minutes à feu moyen, jusqu'à ce qu'il soit cuit à cœur.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-02.webp","image_alt":"Salade de poulet et avocat: Pocher le poulet"},{"title":"Effilocher le poulet","content":"Sortir le poulet, le laisser tiédir quelques minutes et l'effilocher avec deux fourchettes.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-03.webp","image_alt":"Salade de poulet et avocat: Effilocher le poulet"},{"title":"Couper les légumes","content":"Couper les avocats en dés, les tomates cerises en deux et l'oignon rouge en fines lanières. Hacher la coriandre.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-04.webp","image_alt":"Salade de poulet et avocat: Couper les légumes"},{"title":"Préparer la vinaigrette","content":"Fouetter dans un bol 3 cuillères à soupe d'huile d'olive avec le jus de 1 citron et demi (environ 45 ml), 1 pincée de sel et 1 pincée de poivre.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-05.webp","image_alt":"Salade de poulet et avocat: Préparer la vinaigrette"},{"title":"Mélanger la salade","content":"Dans un grand saladier, mélanger le poulet effiloché, les tomates, l'oignon et la coriandre avec la vinaigrette.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-06.webp","image_alt":"Salade de poulet et avocat: Mélanger la salade"},{"title":"Ajouter l'avocat","content":"Incorporer l'avocat en dernier, délicatement pour qu'il ne s'écrase pas.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-07.webp","image_alt":"Salade de poulet et avocat: Ajouter l'avocat"},{"title":"Servir","content":"Servir sur un lit de laitue, avec de la coriandre et le demi-citron restant coupé en quartiers.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-08.webp","image_alt":"Salade de poulet et avocat: Servir"}],"image_url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","gallery":[{"url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","alt":"Salade de poulet et avocat"}],"notes":"Pour garder le poulet juteux, ne le cuisez pas plus que nécessaire et laissez-le tiédir avant de l'effilocher. Choisissez des avocats mûrs mais fermes, qui se coupent en dés sans s'écraser. Ajoutez l'avocat juste avant de servir, car il noircit à l'air ; le jus de citron aide à ralentir cela. Si vous préparez la salade à l'avance, conservez l'avocat et la vinaigrette séparément. Elle se garde jusqu'à 2 jours au réfrigérateur, avec l'avocat frais ajouté au dernier moment.","nutrition":{"calories":373,"protein_g":30.9,"carbs_g":11,"fat_g":23.5,"sodium_mg":80,"serving_size":"1 portion (1/4 de la recette)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 4 portions. On utilise 500 g de blanc de poulet cru, 270 g de chair d'avocat, 200 g de tomates cerises, 60 g d'oignon rouge, 15 g de coriandre, 200 g de laitue, 40,5 g d'huile d'olive et 46 g de jus de citron. Le sel, le poivre et les quartiers de citron pour servir ne sont pas comptés.","note":"Estimation par portion. Le blanc de poulet est calculé cru et sans peau ; le poids de la chair d'avocat varie selon sa taille. On ne déduit pas ce que le poulet perd à la cuisson."},"seo":{"title":"Salade de poulet et avocat, facile et fraîche | Manual de Cocina","description":"Salade de poulet et avocat aux tomates cerises, oignon rouge et coriandre, assaisonnée de citron et d'huile d'olive. Pour 4 personnes, prête en 30 minutes.","image_variants":["/recetas/ensalada-de-pollo-y-aguacate/portada-1x1.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-4x3.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-16x9.webp"],"faq":[{"q":"Comment éviter que l'avocat noircisse dans la salade ?","a":"L'ajouter juste avant de servir et le mélanger délicatement. Le jus de citron de la vinaigrette aide à ralentir le noircissement."},{"q":"Puis-je utiliser du poulet déjà cuit ?","a":"Oui. Effilocher du poulet cuit ou rôti et sauter l'étape de cuisson ; seules les 15 minutes de pochage du blanc sont économisées."},{"q":"Peut-on préparer la salade à l'avance ?","a":"Oui, jusqu'à 2 jours à l'avance au réfrigérateur. Conserver l'avocat et la vinaigrette séparément et les mélanger juste avant de servir."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"00142d74-af75-56b5-91ac-684c4bdfe5b9","recipe_group_id":"5db2c8e6-a3f2-4be8-84b8-620b6ade903c","language":"it","slug":"insalata-di-pollo-e-avocado","public_path":"/it/insalata-di-pollo-e-avocado","source_url":null,"title":"Insalata di pollo e avocado","excerpt":"Insalata di pollo e avocado con pomodorini, cipolla rossa e coriandolo, condita con limone e olio d'oliva. Per 4 persone, pronta in 30 minuti.","summary":"L'insalata di pollo e avocado si prepara lessando il petto di pollo in acqua salata, sfilacciandolo e mescolandolo con pomodorini, cipolla rossa e coriandolo in un condimento di olio d'oliva e limone. L'avocado si aggiunge per ultimo perché non si sfaldi, e si serve su un letto di lattuga.\n\nL'insalata richiede 30 minuti tra preparazione e cottura. Per 4 porzioni.","category":"Insalate","difficulty":"Facile","course":"Piatto principale","cuisine":"Latinoamericana","prep_time_minutes":15,"cook_time_minutes":15,"total_time_minutes":30,"servings":4,"keywords":["insalata di pollo e avocado","ricetta insalata di pollo e avocado","come fare l'insalata di pollo e avocado","insalata di pollo sfilacciato","insalata di pollo con avocado e pomodori","insalata di pollo facile","ensalada de pollo y aguacate"],"ingredients":[{"name":"petto di pollo","amount":"500","unit":"g","group":"Per l'insalata"},{"name":"avocado maturi","amount":"2","unit":"","group":"Per l'insalata"},{"name":"pomodorini","amount":"200","unit":"g","group":"Per l'insalata"},{"name":"cipolla rossa","amount":"1/2","unit":"","group":"Per l'insalata"},{"name":"coriandolo fresco","amount":"15","unit":"g","group":"Per l'insalata"},{"name":"lattuga","amount":"200","unit":"g","group":"Per l'insalata"},{"name":"sale","amount":"1","unit":"cucchiaino","group":"Per l'insalata"},{"name":"olio d'oliva","amount":"3","unit":"cucchiaio","group":"Per il condimento"},{"name":"limoni","amount":"2","unit":"","group":"Per il condimento"},{"name":"pepe nero macinato","amount":"1","unit":"pizzico","group":"Per il condimento"}],"steps":[{"title":"Prepara gli ingredienti","content":"Riunisci 500 g di petto di pollo, 2 avocado maturi, 200 g di pomodorini, 1/2 cipolla rossa, 15 g di coriandolo, 200 g di lattuga e 2 limoni. Lava le verdure e il coriandolo.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-01.webp","image_alt":"Insalata di pollo e avocado: Prepara gli ingredienti"},{"title":"Lessa il pollo","content":"Metti il petto di pollo in una pentola, coprilo d'acqua, aggiungi 1 cucchiaino di sale e cuoci per 15 minuti a fuoco medio, finché è cotto all'interno.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-02.webp","image_alt":"Insalata di pollo e avocado: Lessa il pollo"},{"title":"Sfilaccia il pollo","content":"Togli il pollo, lascialo intiepidire per qualche minuto e sfilaccialo con due forchette.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-03.webp","image_alt":"Insalata di pollo e avocado: Sfilaccia il pollo"},{"title":"Taglia le verdure","content":"Taglia gli avocado a cubetti, i pomodorini a metà e la cipolla rossa a listarelle sottili. Trita il coriandolo.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-04.webp","image_alt":"Insalata di pollo e avocado: Taglia le verdure"},{"title":"Prepara il condimento","content":"In una ciotola sbatti 3 cucchiai di olio d'oliva con il succo di 1 limone e mezzo (circa 45 ml), 1 pizzico di sale e 1 pizzico di pepe.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-05.webp","image_alt":"Insalata di pollo e avocado: Prepara il condimento"},{"title":"Mescola l'insalata","content":"In una ciotola capiente mescola il pollo sfilacciato, i pomodorini, la cipolla e il coriandolo con il condimento.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-06.webp","image_alt":"Insalata di pollo e avocado: Mescola l'insalata"},{"title":"Aggiungi l'avocado","content":"Incorpora l'avocado per ultimo, con movimenti delicati perché non si sfaldi.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-07.webp","image_alt":"Insalata di pollo e avocado: Aggiungi l'avocado"},{"title":"Servi","content":"Servi su un letto di lattuga, con il coriandolo sopra e il mezzo limone rimasto tagliato a spicchi.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-08.webp","image_alt":"Insalata di pollo e avocado: Servi"}],"image_url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","gallery":[{"url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","alt":"Insalata di pollo e avocado"}],"notes":"Per mantenere il pollo succoso, non cuocerlo più del necessario e lasciarlo intiepidire prima di sfilacciarlo. Scegli avocado maturi ma sodi, che si tagliano a cubetti senza sfaldarsi. Aggiungi l'avocado poco prima di servire, perché si scurisce a contatto con l'aria; il succo di limone aiuta a rallentarlo. Se prepari l'insalata in anticipo, conserva l'avocado e il condimento separati. Si conserva fino a 2 giorni in frigorifero, con l'avocado fresco aggiunto all'ultimo momento.","nutrition":{"calories":373,"protein_g":30.9,"carbs_g":11,"fat_g":23.5,"sodium_mg":80,"serving_size":"1 porzione (1/4 della ricetta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per i pesi degli ingredienti e divisi per 4 porzioni. Si usano 500 g di petto di pollo crudo, 270 g di polpa di avocado, 200 g di pomodorini, 60 g di cipolla rossa, 15 g di coriandolo, 200 g di lattuga, 40,5 g di olio d'oliva e 46 g di succo di limone. Sale, pepe e gli spicchi di limone per servire non sono conteggiati.","note":"Stima per porzione. Il petto di pollo è calcolato crudo e senza pelle; il peso della polpa di avocado varia con la dimensione. Non si detrae ciò che il pollo perde con la cottura."},"seo":{"title":"Insalata di pollo e avocado, facile e fresca | Manual de Cocina","description":"Insalata di pollo e avocado con pomodorini, cipolla rossa e coriandolo, condita con limone e olio d'oliva. Per 4 persone, pronta in 30 minuti.","image_variants":["/recetas/ensalada-de-pollo-y-aguacate/portada-1x1.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-4x3.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-16x9.webp"],"faq":[{"q":"Come evito che l'avocado si scurisca nell'insalata?","a":"Aggiungilo poco prima di servire e incorporalo delicatamente. Il succo di limone del condimento aiuta a rallentare l'annerimento."},{"q":"Posso usare pollo già cotto?","a":"Sì. Sfilaccia il pollo cotto o arrosto e salta il passaggio di cottura; si risparmiano solo i 15 minuti di lessatura del petto."},{"q":"Si può preparare in anticipo?","a":"Sì, fino a 2 giorni prima in frigorifero. Conserva l'avocado e il condimento separati e mescolali poco prima di servire."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"6a67b44b-08f3-5c18-af41-0c5d6470d593","recipe_group_id":"5db2c8e6-a3f2-4be8-84b8-620b6ade903c","language":"ja","slug":"チキンとアボカドのサラダ","public_path":"/ja/チキンとアボカドのサラダ","source_url":null,"title":"チキンとアボカドのサラダ","excerpt":"ミニトマト、紫玉ねぎ、パクチーを、レモンとオリーブオイルで和えたチキンとアボカドのサラダ。4人分、30分で完成。","summary":"チキンとアボカドのサラダは、鶏むね肉を塩ゆでして裂き、ミニトマト、紫玉ねぎ、パクチーとともにオリーブオイルとレモンのドレッシングで和えて作ります。アボカドは崩れないように最後に加え、レタスを敷いた上に盛り付けます。\n\n下ごしらえから調理まで30分かかります。4人分です。","category":"サラダ","difficulty":"簡単","course":"主菜","cuisine":"ラテンアメリカ料理","prep_time_minutes":15,"cook_time_minutes":15,"total_time_minutes":30,"servings":4,"keywords":["チキンとアボカドのサラダ","チキン アボカド サラダ レシピ","チキン アボカド サラダ 作り方","鶏むね肉 サラダ 裂く","鶏肉 アボカド トマト サラダ","鶏肉 サラダ 簡単","エンサラダ・デ・ポージョ・イ・アグアカテ"],"ingredients":[{"name":"鶏むね肉","amount":"500","unit":"g","group":"サラダ用"},{"name":"熟したアボカド","amount":"2","unit":"","group":"サラダ用"},{"name":"ミニトマト","amount":"200","unit":"g","group":"サラダ用"},{"name":"紫玉ねぎ","amount":"1/2","unit":"","group":"サラダ用"},{"name":"パクチー（生）","amount":"15","unit":"g","group":"サラダ用"},{"name":"レタス","amount":"200","unit":"g","group":"サラダ用"},{"name":"塩","amount":"1","unit":"小さじ","group":"サラダ用"},{"name":"オリーブオイル","amount":"3","unit":"大さじ","group":"ドレッシング用"},{"name":"レモン","amount":"2","unit":"","group":"ドレッシング用"},{"name":"黒こしょう（挽いたもの）","amount":"1","unit":"ひとつまみ","group":"ドレッシング用"}],"steps":[{"title":"材料を準備する","content":"鶏むね肉500g、熟したアボカド2個、ミニトマト200g、紫玉ねぎ1/2個、パクチー15g、レタス200g、レモン2個を用意します。野菜とパクチーを洗います。","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-01.webp","image_alt":"チキンとアボカドのサラダ: 材料を準備する"},{"title":"鶏むね肉をゆでる","content":"鍋に鶏むね肉を入れ、水をかぶるくらいに注ぎ、塩小さじ1を加えて、中火で中まで火が通るまで15分ゆでます。","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-02.webp","image_alt":"チキンとアボカドのサラダ: 鶏むね肉をゆでる"},{"title":"鶏肉を裂く","content":"鶏肉を取り出し、数分おいて粗熱を取り、フォーク2本で裂きます。","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-03.webp","image_alt":"チキンとアボカドのサラダ: 鶏肉を裂く"},{"title":"野菜を切る","content":"アボカドはさいの目に、ミニトマトは半分に、紫玉ねぎは薄切りにします。パクチーはみじん切りにします。","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-04.webp","image_alt":"チキンとアボカドのサラダ: 野菜を切る"},{"title":"ドレッシングを作る","content":"ボウルにオリーブオイル大さじ3、レモン1個半の果汁（約45ml）、塩ひとつまみ、こしょうひとつまみを入れて混ぜます。","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-05.webp","image_alt":"チキンとアボカドのサラダ: ドレッシングを作る"},{"title":"サラダを混ぜる","content":"大きなボウルに、裂いた鶏肉、ミニトマト、紫玉ねぎ、パクチーを入れ、ドレッシングで和えます。","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-06.webp","image_alt":"チキンとアボカドのサラダ: サラダを混ぜる"},{"title":"アボカドを加える","content":"崩れないように、最後にアボカドをやさしく混ぜ合わせます。","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-07.webp","image_alt":"チキンとアボカドのサラダ: アボカドを加える"},{"title":"盛り付ける","content":"レタスを敷いた上に盛り、パクチーをのせ、残りの半分のレモンをくし形に切って添えます。","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-08.webp","image_alt":"チキンとアボカドのサラダ: 盛り付ける"}],"image_url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","gallery":[{"url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","alt":"チキンとアボカドのサラダ"}],"notes":"鶏肉をジューシーに仕上げるには、必要以上に火を通さず、裂く前に粗熱を取ります。アボカドは、さいの目に切っても崩れない、熟していてもしっかりしたものを選びます。アボカドは空気に触れると変色するので、食べる直前に加えます。レモン汁が変色を遅らせます。作り置きする場合は、アボカドとドレッシングを別に保存してください。冷蔵庫で2日間保存でき、アボカドは食べる直前に新しく加えます。","nutrition":{"calories":373,"protein_g":30.9,"carbs_g":11,"fat_g":23.5,"sodium_mg":80,"serving_size":"1人分（レシピの1/4）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、4人分で割って合計しています。生の鶏むね肉500g、アボカドの果肉270g、ミニトマト200g、紫玉ねぎ60g、パクチー15g、レタス200g、オリーブオイル40.5g、レモン汁46gを使用しています。塩、こしょう、添えるレモンのくし形切りは計算に含めていません。","note":"1人分の目安です。鶏むね肉は皮なしの生として計算しており、アボカドの果肉の重さは大きさによって変わります。加熱で鶏肉から失われる分は差し引いていません。"},"seo":{"title":"チキンとアボカドのサラダの作り方｜簡単でさっぱり | Manual de Cocina","description":"ミニトマト、紫玉ねぎ、パクチーを、レモンとオリーブオイルで和えたチキンとアボカドのサラダ。4人分、30分で完成。手順を写真付きで解説します。","image_variants":["/recetas/ensalada-de-pollo-y-aguacate/portada-1x1.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-4x3.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-16x9.webp"],"faq":[{"q":"サラダのアボカドが変色しないようにするには？","a":"食べる直前に加えて、やさしく混ぜます。ドレッシングのレモン汁が変色を遅らせます。"},{"q":"調理済みの鶏肉でも作れますか？","a":"作れます。ゆでた鶏肉やローストチキンを裂いて使い、加熱の手順を省きます。省けるのは鶏むね肉をゆでる15分だけです。"},{"q":"作り置きはできますか？","a":"できます。冷蔵庫で2日前まで。アボカドとドレッシングは別に保存し、食べる直前に混ぜてください。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"714df9d0-e44e-5bbc-8c3e-ae3bf0d56104","recipe_group_id":"5db2c8e6-a3f2-4be8-84b8-620b6ade903c","language":"pt","slug":"salada-de-frango-e-abacate","public_path":"/pt/salada-de-frango-e-abacate","source_url":null,"title":"Salada de frango e abacate","excerpt":"Salada de frango e abacate com tomate-cereja, cebola roxa e coentro, temperada com limão e azeite. Para 4 pessoas, pronta em 30 minutos.","summary":"A salada de frango e abacate é feita cozinhando o peito de frango em água com sal, desfiando e misturando com tomate-cereja, cebola roxa e coentro em um molho de azeite e limão. O abacate entra por último para não desmanchar, e a salada é servida sobre uma cama de alface.\n\nA salada leva 30 minutos entre preparo e cozimento. Rende 4 porções.","category":"Saladas","difficulty":"Fácil","course":"Prato principal","cuisine":"Latino-americana","prep_time_minutes":15,"cook_time_minutes":15,"total_time_minutes":30,"servings":4,"keywords":["salada de frango e abacate","receita de salada de frango e abacate","como fazer salada de frango e abacate","salada de frango desfiado","salada de frango com abacate e tomate","salada de frango fácil","ensalada de pollo y aguacate"],"ingredients":[{"name":"peito de frango","amount":"500","unit":"g","group":"Para a salada"},{"name":"abacates maduros","amount":"2","unit":"","group":"Para a salada"},{"name":"tomate-cereja","amount":"200","unit":"g","group":"Para a salada"},{"name":"cebola roxa","amount":"1/2","unit":"","group":"Para a salada"},{"name":"coentro fresco","amount":"15","unit":"g","group":"Para a salada"},{"name":"alface","amount":"200","unit":"g","group":"Para a salada"},{"name":"sal","amount":"1","unit":"colher de chá","group":"Para a salada"},{"name":"azeite","amount":"3","unit":"colher de sopa","group":"Para o molho"},{"name":"limões","amount":"2","unit":"","group":"Para o molho"},{"name":"pimenta-do-reino moída","amount":"1","unit":"pitada","group":"Para o molho"}],"steps":[{"title":"Prepare os ingredientes","content":"Separe 500 g de peito de frango, 2 abacates maduros, 200 g de tomate-cereja, 1/2 cebola roxa, 15 g de coentro, 200 g de alface e 2 limões. Lave os legumes e o coentro.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-01.webp","image_alt":"Salada de frango e abacate: Prepare os ingredientes"},{"title":"Cozinhe o frango","content":"Coloque o peito de frango em uma panela, cubra com água, junte 1 colher de chá de sal e cozinhe por 15 minutos em fogo médio, até ficar cozido por dentro.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-02.webp","image_alt":"Salada de frango e abacate: Cozinhe o frango"},{"title":"Desfie o frango","content":"Retire o frango, deixe amornar por alguns minutos e desfie com dois garfos.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-03.webp","image_alt":"Salada de frango e abacate: Desfie o frango"},{"title":"Corte os legumes","content":"Corte os abacates em cubos, os tomates-cereja ao meio e a cebola roxa em tiras finas. Pique o coentro.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-04.webp","image_alt":"Salada de frango e abacate: Corte os legumes"},{"title":"Prepare o molho","content":"Em uma tigela, misture 3 colheres de sopa de azeite com o suco de 1 limão e meio (cerca de 45 ml), 1 pitada de sal e 1 pitada de pimenta.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-05.webp","image_alt":"Salada de frango e abacate: Prepare o molho"},{"title":"Misture a salada","content":"Em uma tigela grande, misture o frango desfiado, os tomates, a cebola e o coentro com o molho.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-06.webp","image_alt":"Salada de frango e abacate: Misture a salada"},{"title":"Junte o abacate","content":"Incorpore o abacate por último, com movimentos suaves para não desmanchar.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-07.webp","image_alt":"Salada de frango e abacate: Junte o abacate"},{"title":"Sirva","content":"Sirva sobre uma cama de alface, com coentro por cima e o meio limão restante cortado em gomos.","image_url":"/recetas/ensalada-de-pollo-y-aguacate/paso-08.webp","image_alt":"Salada de frango e abacate: Sirva"}],"image_url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","gallery":[{"url":"/recetas/ensalada-de-pollo-y-aguacate/portada.webp","alt":"Salada de frango e abacate"}],"notes":"Para o frango ficar suculento, não cozinhe além do necessário e deixe amornar antes de desfiar. Escolha abacates maduros, mas firmes, que possam ser cortados em cubos sem desmanchar. Junte o abacate pouco antes de servir, porque escurece em contato com o ar; o suco de limão ajuda a retardar isso. Se preparar a salada com antecedência, guarde o abacate e o molho separados. Conserva-se até 2 dias na geladeira, com o abacate fresco acrescentado na hora.","nutrition":{"calories":373,"protein_g":30.9,"carbs_g":11,"fat_g":23.5,"sodium_mg":80,"serving_size":"1 porção (1/4 da receita)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 4 porções. Usam-se 500 g de peito de frango cru, 270 g de polpa de abacate, 200 g de tomate-cereja, 60 g de cebola roxa, 15 g de coentro, 200 g de alface, 40,5 g de azeite e 46 g de suco de limão. Sal, pimenta-do-reino e os gomos de limão para servir não são contados.","note":"Estimativa por porção. O peito de frango é calculado cru e sem pele; o peso da polpa do abacate varia com o tamanho. Não se desconta o que o frango perde ao cozinhar."},"seo":{"title":"Salada de frango e abacate fácil e fresca | Manual de Cocina","description":"Salada de frango e abacate com tomate-cereja, cebola roxa e coentro, temperada com limão e azeite. Para 4 pessoas, pronta em 30 minutos.","image_variants":["/recetas/ensalada-de-pollo-y-aguacate/portada-1x1.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-4x3.webp","/recetas/ensalada-de-pollo-y-aguacate/portada-16x9.webp"],"faq":[{"q":"Como evitar que o abacate escureça na salada?","a":"Junte-o pouco antes de servir e misture com cuidado. O suco de limão do molho ajuda a retardar o escurecimento."},{"q":"Posso usar frango já cozido?","a":"Pode. Desfie o frango cozido ou assado e pule a etapa de cozimento; só se economizam os 15 minutos de cozimento do peito."},{"q":"Dá para preparar com antecedência?","a":"Dá, até 2 dias antes na geladeira. Guarde o abacate e o molho separados e misture pouco antes de servir."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/ensalada-de-pollo-y-aguacate') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
